  217: "یک مدل به ما کمک می‌کند برنامه را بسازیم؛ یک مدل هم در برنامهٔ ساخته‌شده به درخواستِ کاربران پاسخ می‌دهد. این دو می‌توانند متفاوت باشند. برای ساخت، کیفیتِ طراحی و حلِ مسئله مهم است. برای اجرا، هزینهٔ تکرارشونده را همراه با کیفیت، سرعت و حساسیتِ کار می‌سنجیم. گذار به صفحهٔ بعد: در اجرای خدمت، حساسیتِ کار و مسیرِ اعتماد چه تغییری در انتخاب می‌دهند؟ گذار به صفحهٔ بعد: در زمانِ اجرای خدمت، حساسیتِ کار چه اثری روی مسیرِ اعتماد دارد؟",
